+#ifdef HNI_SUPPORT_5G_MODULE
+static int requestEnsureIPPass1Once(PROFILE_T *profile)
+{
+    int err;
+    ATResponse *p_response = NULL;
+
+    if (profile == NULL)
+        return -1;
+
+    if (requestGetIPPass(profile) == 0)
+    {
+        if (profile->ippass == 1)
+        {
+            dbg_time("GTIPPASS Already 1 (persisted).");
+            return 0;
+        }
+        dbg_time("GTIPPASS is %d, set to 1.", profile->ippass);
+    }
+    else
+    {
+        dbg_time("GTIPPASS Query failed, try set to 1 anyway.");
+    }
+
+    err = at_send_command("AT+GTIPPASS=1", &p_response);
+    if (at_response_error(err, p_response))
+    {
+        safe_at_response_free(p_response);
+        return -1;
+    }
+
+    safe_at_response_free(p_response);
+
+    if (requestGetIPPass(profile) == 0)
+    {
+        dbg_time("GTIPPASS after set = %d", profile->ippass);
+        return (profile->ippass == 1) ? 0 : -1;
+    }
+
+    return 0;
+}
+#endif

