--- a/tclinux_phoenix/app_bsp/private/API/ecnt_blapi/system/blapi_system.c
+++ b/tclinux_phoenix/app_bsp/private/API/ecnt_blapi/system/blapi_system.c
@@ -3152,6 +3152,60 @@ int blapi_system_image_check(char *file)
 	return 0;
 }

+#if defined(HNI_SUPPORT_COMMON)
+int blapi_system_get_partition_dev(char boot_flag, char *kernel_dev, size_t kernel_len, char *rootfs_dev, size_t rootfs_len)
+{
+	if (kernel_dev)
+		snprintf(kernel_dev, kernel_len, "%s", (boot_flag == 0) ? "/dev/mtd1" : "/dev/mtd3"); // kernel - kernel_slave
+	if (rootfs_dev)
+		snprintf(rootfs_dev, rootfs_len, "%s", (boot_flag == 0) ? "/dev/mtd2" : "/dev/mtd4"); // filesystem - filesystem_slave
+
+	return 0;
+}
+
+int blapi_system_get_kernel_len(void)
+{
+	return IMAGE_SPLIT_OFFSET;
+}
+
+int blapi_system_get_rootfs_len(char boot_flag)
+{
+	int fd = -1;
+	ssize_t read_size;
+	unsigned int data = 0;
+	int rootfs_len = 0;
+	char kernel_dev[16] = {0};
+
+	blapi_system_get_partition_dev(boot_flag, kernel_dev, sizeof(kernel_dev), NULL, 0);
+
+	if((fd = open(kernel_dev, O_RDONLY)) == -1)
+	{
+		ecnt_blapi_printf("open file %s fail\n", kernel_dev);
+		return -1;
+	}
+
+	if(lseek(fd, IMAGE_SPLIT_OFFSET - 8, SEEK_SET) == (off_t) - 1)
+	{
+		ecnt_blapi_printf("seek in %s fail\n", kernel_dev);
+		close(fd);
+		return -1;
+	}
+
+	read_size = read(fd, &data, sizeof(data));
+	if(read_size != sizeof(data))
+	{
+		ecnt_blapi_printf("fail -- only read %zd\n", read_size);
+		close(fd);
+		return -1;
+	}
+
+	rootfs_len = (int)htonl(data);
+
+	close(fd);
+	return rootfs_len;
+}
+#endif
+
 int blapi_system_get_image_version(char *file, char *buf, size_t size)
 {
 	int fd = -1;
