+static const char* wa_find_role_by_almac(struct json_object *topo, const char *almac)
+{
+    if (!topo || !almac)
+        return NULL;
+
+    int topoLen = json_object_array_length(topo);
+    for (int i = 0; i < topoLen; i++) {
+        struct json_object *node = json_object_array_get_idx(topo, i);
+        const char *mac = json_object_get_string(json_object_object_get(node, "AL MAC"));
+        if (mac && almac && strcmp(mac, almac) == 0) {
+            return json_object_get_string(json_object_object_get(node, "Device role"));
+        }
+    }
+    return NULL;
+}
+
+static void wa_fill_bh_wifi_infor(connected_client_info_t *neighbour, connected_client_list_t *wifiClientList)
+{
+    if (!neighbour || !wifiClientList)
+        return;
+
+    for (int i = 0; i < wifiClientList->count; i++) {
+        connected_client_info_t *client = &wifiClientList->sta[i];
+        if (client->isBhSta && strcmp(neighbour->clientMac, client->clientMac) == 0) {
+            snprintf(neighbour->phyMode, sizeof(neighbour->phyMode), "%s", client->phyMode);
+            snprintf(neighbour->ssid, sizeof(neighbour->ssid), "%s", client->ssid);
+            snprintf(neighbour->bssid, sizeof(neighbour->bssid), "%s", client->bssid);
+            return;
+        }
+    }
+}
+
+static int wa_add_neighbour_entry(connected_client_list_t *neighbourList, const char *almac, const char *role,
+                        const char *medium, const char *clientMac, int rssi, connected_client_list_t *wifiClientList)
+{
+    if (!neighbourList || !almac || !role || !medium || !clientMac)
+        return -1;
+
+    if (neighbourList->count >= MAX_STA_PER_NODE)
+        return neighbourList->count;
+
+    for (int i = 0; i < neighbourList->count; i++) {
+        if (strcmp(neighbourList->sta[i].almac, almac) == 0
+            && strcmp(neighbourList->sta[i].clientMac, clientMac) == 0)
+        {
+            return neighbourList->count;
+        }
+    }
+
+    connected_client_info_t *n = &neighbourList->sta[neighbourList->count++];
+    memset(n, 0, sizeof(*n));
+
+    snprintf(n->almac, sizeof(n->almac), "%s", almac);
+    snprintf(n->role, sizeof(n->role), "%s", role);
+    snprintf(n->medium, sizeof(n->medium), "%s", medium);
+    snprintf(n->band, sizeof(n->band), "%s", medium);
+    snprintf(n->clientMac, sizeof(n->clientMac), "%s", clientMac);
+
+    n->rssi = rssi;
+    n->accessTime = 0;
+    n->isBhSta = true;
+
+    if (strcmp(medium, "Ethernet") != 0) {
+        wa_fill_bh_wifi_infor(n, wifiClientList);
+    }
+
+    return neighbourList->count;
+}
+
+static int wa_get_direct_neighbour_list(const char *alMac, struct json_object *root, 
+                        connected_client_list_t *neighbourList, connected_client_list_t *wifiClientList)
+{
+    struct json_object *topo_arr = NULL;
+
+    if (!alMac || !root || !neighbourList || !wifiClientList)
+        return -1;
+
+    memset(neighbourList, 0, sizeof(*neighbourList));
+
+    if (!json_object_object_get_ex(root, "topology information", &topo_arr)
+        || !json_object_is_type(topo_arr, json_type_array))
+    {
+        return -1;
+    }
+
+    const char *upstream_al = NULL;
+    struct json_object *self_bh_arr = NULL;
+    int topo_len = json_object_array_length(topo_arr);
+
+    for (int i = 0; i < topo_len; i++) {
+        struct json_object *node = json_object_array_get_idx(topo_arr, i);
+
+        const char *nodeAl = json_object_get_string(json_object_object_get(node, "AL MAC"));
+        const char *role = json_object_get_string(json_object_object_get(node, "Device role"));
+        const char *upstream = json_object_get_string(json_object_object_get(node, "Upstream 1905 device"));
+
+        if (nodeAl && strcmp(nodeAl, alMac) == 0) {
+            upstream_al = upstream;
+            json_object_object_get_ex(node, "BH Info", &self_bh_arr);
+        }
+
+        if (!upstream || strcmp(upstream, alMac) != 0)
+            continue;
+
+        struct json_object *bh_arr = NULL;
+        if (!json_object_object_get_ex(node, "BH Info", &bh_arr) || !json_object_is_type(bh_arr, json_type_array))
+            continue;
+
+        int bh_len = json_object_array_length(bh_arr);
+        for (int b = 0; b < bh_len; b++) {
+            struct json_object *bh = json_object_array_get_idx(bh_arr, b);
+            const char *medium = json_object_get_string(json_object_object_get(bh, "Backhaul Medium Type"));
+            if (!medium)
+                continue;
+
+            int rssi = 0;
+            struct json_object *jrssi = json_object_object_get(bh, "RSSI");
+            if (jrssi) {
+                const char *sr = json_object_get_string(jrssi);
+                if (sr && strcmp(sr, "NA") != 0)
+                    rssi = atoi(sr);
+            }
+
+            const char *clientMac = NULL;
+            if (strcmp(medium, "Ethernet") == 0)
+                clientMac = nodeAl;
+            else
+                clientMac = json_object_get_string(json_object_object_get(bh, "connected iface addr"));
+
+            if (!nodeAl || !role || !clientMac)
+                continue;
+
+            wa_add_neighbour_entry(neighbourList, nodeAl, role, medium, clientMac, rssi, wifiClientList);
+        }
+    }
+
+    if (upstream_al && self_bh_arr && json_object_is_type(self_bh_arr, json_type_array)) {
+        const char *up_role = wa_find_role_by_almac(topo_arr, upstream_al);
+        if (!up_role)
+            up_role = "01";
+
+        int bh_len = json_object_array_length(self_bh_arr);
+        for (int b = 0; b < bh_len; b++) {
+            struct json_object *bh = json_object_array_get_idx(self_bh_arr, b);
+
+            const char *nbr = json_object_get_string(json_object_object_get(bh, "neighbor almac addr"));
+            if (!nbr || strcmp(nbr, upstream_al) != 0)
+                continue;
+
+            const char *medium = json_object_get_string(json_object_object_get(bh, "Backhaul Medium Type"));
+            if (!medium)
+                continue;
+
+            int rssi = 0;
+            struct json_object *jrssi = json_object_object_get(bh, "RSSI");
+            if (jrssi) {
+                const char *sr = json_object_get_string(jrssi);
+                if (sr && strcmp(sr, "NA") != 0)
+                    rssi = atoi(sr);
+            }
+
+            const char *clientMac = NULL;
+            if (strcmp(medium, "Ethernet") == 0) 
+                clientMac = upstream_al;
+            else 
+                clientMac = json_object_get_string(json_object_object_get(bh, "connected iface addr"));
+
+            if (!clientMac)
+                continue;
+
+            wa_add_neighbour_entry(neighbourList, upstream_al, up_role, medium, clientMac, rssi, wifiClientList);
+        }
+    }
+
+    return neighbourList->count;
+}
